<?php defined( 'ABSPATH' ) || exit; $registry = ALGQ_Command_Center_Health_Monitor::plugin_registry(); $checks = ALGQ_Command_Center_Health_Monitor::checks(); ?>
<div class="wrap algq-command-center algq-admin-shell"><h1><?php echo esc_html__( 'Algonquian Plugin Library', 'algq-command-center' ); ?></h1><div class="algq-plugin-grid"><?php foreach ( $registry as $key => $plugin ) : $check = $checks[ 'plugin_' . sanitize_key( $key ) ] ?? array( 'status' => 'warning', 'message' => 'Unknown' ); ?><article class="algq-plugin-card"><span class="algq-status algq-status-<?php echo esc_attr( sanitize_key( (string) $check['status'] ) ); ?>"><?php echo esc_html( ucfirst( (string) $check['status'] ) ); ?></span><h3><?php echo esc_html( (string) $plugin['label'] ); ?></h3><p><?php echo esc_html( (string) $check['message'] ); ?></p><small><?php echo ! empty( $plugin['required'] ) ? esc_html__( 'Protected foundation / required', 'algq-command-center' ) : esc_html__( 'Optional integration', 'algq-command-center' ); ?></small></article><?php endforeach; ?></div></div>
